"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/morphic-command-palette/variants/01-default";
export interface ArtemisMorphicCommandPaletteProps {
  className?: string;
}
export function ArtemisMorphicCommandPalette({ className }: ArtemisMorphicCommandPaletteProps) {
  return (
    <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}>
      <Variant0 />
    </ArtemisScope>
  );
}

"use client";
// @zeus-internal
import { Dialog, DialogBackdrop, DialogPanel, DialogTitle } from "../../../lib/headless";
import { AnimatePresence, MotionConfig, motion, useReducedMotion } from "motion/react";
import { type KeyboardEvent, type ReactNode, useEffect, useId, useMemo, useRef, useState } from "react";
import { ArtemisMorphicTooltip, ArtemisMorphicTooltipProvider } from "../../../foundations/morphic-tooltip";
import { artemisSearchCommands } from "../../../lib/command-search";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_LAYOUT } from "../../../lib/ease";
type Command = {
    label: string;
    group: string;
    keywords: string[];
    icon: ReactNode;
};
function Svg({ name, size, children }: {
    name: string;
    size: string;
    children: ReactNode;
}) {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide ${name} ${size}`} aria-hidden="true">
      {children}
    </svg>);
}
const ICON = "art:size-4 art:shrink-0 art:text-muted-foreground";
const COMMANDS: readonly Command[] = [
    {
        label: "Home",
        group: "Navigation",
        keywords: ["dashboard", "overview"],
        icon: (<Svg name="lucide-house" size={ICON}>
        <path d="M15 21v-8a1 1 0 0 0-1-1h-4a1 1 0 0 0-1 1v8"/>
        <path d="M3 10a2 2 0 0 1 .709-1.528l7-6a2 2 0 0 1 2.582 0l7 6A2 2 0 0 1 21 10v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/>
      </Svg>),
    },
    {
        label: "Projects",
        group: "Navigation",
        keywords: [],
        icon: (<Svg name="lucide-folder" size={ICON}>
        <path d="M20 20a2 2 0 0 0 2-2V8a2 2 0 0 0-2-2h-7.9a2 2 0 0 1-1.69-.9L9.6 3.9A2 2 0 0 0 7.93 3H4a2 2 0 0 0-2 2v13a2 2 0 0 0 2 2Z"/>
      </Svg>),
    },
    {
        label: "Team",
        group: "Navigation",
        keywords: ["members", "people"],
        icon: (<Svg name="lucide-users-round" size={ICON}>
        <path d="M18 21a8 8 0 0 0-16 0"/>
        <circle cx="10" cy="8" r="5"/>
        <path d="M22 20c0-3.37-2-6.5-4-8a5 5 0 0 0-.45-8.3"/>
      </Svg>),
    },
    {
        label: "Settings",
        group: "Navigation",
        keywords: ["preferences", "account"],
        icon: (<Svg name="art:lucide-settings2 art:lucide-settings-2" size={ICON}>
        <path d="M14 17H5"/>
        <path d="M19 7h-9"/>
        <circle cx="17" cy="17" r="3"/>
        <circle cx="7" cy="7" r="3"/>
      </Svg>),
    },
    {
        label: "New document",
        group: "Actions",
        keywords: ["create", "write", "page"],
        icon: (<Svg name="lucide-file-plus-corner" size={ICON}>
        <path d="M11.35 22H6a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h8a2.4 2.4 0 0 1 1.706.706l3.588 3.588A2.4 2.4 0 0 1 20 8v5.35"/>
        <path d="M14 2v5a1 1 0 0 0 1 1h5"/>
        <path d="M14 19h6"/>
        <path d="M17 16v6"/>
      </Svg>),
    },
    {
        label: "New project",
        group: "Actions",
        keywords: ["create", "folder"],
        icon: (<Svg name="lucide-folder-plus" size={ICON}>
        <path d="M12 10v6"/>
        <path d="M9 13h6"/>
        <path d="M20 20a2 2 0 0 0 2-2V8a2 2 0 0 0-2-2h-7.9a2 2 0 0 1-1.69-.9L9.6 3.9A2 2 0 0 0 7.93 3H4a2 2 0 0 0-2 2v13a2 2 0 0 0 2 2Z"/>
      </Svg>),
    },
    {
        label: "Keyboard shortcuts",
        group: "Actions",
        keywords: ["keys", "help"],
        icon: (<Svg name="lucide-keyboard" size={ICON}>
        <path d="M10 8h.01"/>
        <path d="M12 12h.01"/>
        <path d="M14 8h.01"/>
        <path d="M16 12h.01"/>
        <path d="M18 8h.01"/>
        <path d="M6 8h.01"/>
        <path d="M7 16h10"/>
        <path d="M8 12h.01"/>
        <rect width="20" height="16" x="2" y="4" rx="2"/>
      </Svg>),
    },
];
function grouped(list: readonly Command[]) {
    const groups: {
        name: string;
        items: Command[];
    }[] = [];
    for (const c of list) {
        const g = groups.find((x) => x.name === c.group);
        if (g)
            g.items.push(c);
        else
            groups.push({ name: c.group, items: [c] });
    }
    return groups;
}
const GHOST = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground";
const FADE = { duration: 0.15, ease: ARTEMIS_EASE_OUT };
export default function MorphicCommandPaletteDefault() {
    const id = useId();
    const reduce = useReducedMotion();
    const [open, setOpen] = useState(false);
    const [mounted, setMounted] = useState(false);
    const [query, setQuery] = useState("");
    const [active, setActive] = useState(0);
    const [selected, setSelected] = useState("");
    const listRef = useRef<HTMLDivElement>(null);
    const groups = useMemo(() => grouped(artemisSearchCommands([...COMMANDS], query)), [query]);
    const flat = useMemo(() => groups.flatMap((g) => g.items), [groups]);
    const count = flat.length;
    const show = () => {
        setQuery("");
        setActive(0);
        setMounted(true);
        setOpen(true);
    };
    const close = () => {
        if (document.activeElement instanceof HTMLElement)
            document.activeElement.blur();
        setOpen(false);
    };
    const choose = (c: Command) => {
        setSelected(`Selected: ${c.label}`);
        close();
    };
    useEffect(() => {
        const onKey = (e: globalThis.KeyboardEvent) => {
            if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "j") {
                e.preventDefault();
                if (open)
                    close();
                else
                    show();
            }
        };
        document.addEventListener("keydown", onKey);
        return () => document.removeEventListener("keydown", onKey);
    });
    useEffect(() => {
        listRef.current?.querySelector(`[data-index="${active}"]`)?.scrollIntoView({ block: "nearest" });
    }, [active]);
    const onInputKey = (e: KeyboardEvent<HTMLInputElement>) => {
        if (!count)
            return;
        if (e.key === "ArrowDown")
            setActive((i) => Math.min(count - 1, i + 1));
        else if (e.key === "ArrowUp")
            setActive((i) => Math.max(0, i - 1));
        else if (e.key === "Home")
            setActive(0);
        else if (e.key === "End")
            setActive(count - 1);
        else if (e.key === "Enter")
            choose(flat[active]);
        else
            return;
        e.preventDefault();
    };
    const layout = reduce ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT;
    const fade = reduce ? { duration: 0 } : FADE;
    return (<ArtemisMorphicTooltipProvider>
      <div className="art:flex art:w-full art:flex-col art:items-center art:justify-center art:gap-3">
        <button type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:hover:text-foreground art:gap-2 art:relative art:isolate art:rounded-full art:bg-transparent art:px-4 art:text-sm art:text-foreground art:outline-none art:hover:bg-transparent art:focus-visible:ring-2 art:focus-visible:ring-ring art:h-9" aria-haspopup="dialog" aria-expanded={open} aria-controls={`${id}-dialog`} style={{ visibility: open ? "hidden" : "visible" }} onClick={show}>
          <motion.span layoutId={`${id}-surface`} aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0 art:-z-10 art:rounded-full art:border art:border-border art:bg-background" transition={layout}/>
          <motion.span className="art:flex art:min-w-0 art:flex-1 art:items-center art:justify-center art:gap-3" initial={false} animate={{ opacity: open ? 0 : 1 }} transition={reduce ? { duration: 0 } : { duration: 0.15, ease: "easeOut" }}>
            <Svg name="lucide-search" size="art:size-4 art:text-muted-foreground">
              <path d="m21 21-4.34-4.34"/>
              <circle cx="11" cy="11" r="8"/>
            </Svg>
            <span>{"Open command palette"}</span>
            <kbd className="art:ml-3 art:text-xs art:text-muted-foreground">{"\u2318 / Ctrl J"}</kbd>
          </motion.span>
        </button>
        <output className="art:min-h-4 art:text-xs art:text-muted-foreground">{selected}</output>
      </div>
      {mounted && (<Dialog static open={open} onClose={close} id={`${id}-dialog`} className="art:fixed art:inset-0 art:z-[100]" inert={!open}>
          <AnimatePresence onExitComplete={() => setMounted(false)}>
            {open && (<MotionConfig key="backdrop" transition={fade}>
                <DialogBackdrop as={motion.div} className="art:fixed art:inset-0 art:bg-foreground/10 art:backdrop-blur-md" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}/>
              </MotionConfig>)}
            {open && (<div key="frame" className="art:pointer-events-none art:fixed art:inset-0 art:flex art:items-start art:justify-center art:px-3 art:pb-3 art:pt-[min(16vh,6rem)] art:sm:px-6 art:sm:pb-6">
                <MotionConfig transition={layout}>
                <DialogPanel as={motion.div} layoutId={`${id}-surface`} className="art:pointer-events-auto art:flex art:max-h-[calc(100dvh-7rem)] art:w-full art:max-w-lg art:flex-col art:overflow-hidden art:rounded-2xl art:border art:border-border art:bg-background art:text-foreground" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0, transition: fade }}>
                  <motion.div layout className="art:flex art:min-h-0 art:flex-col" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} transition={fade}>
                    <DialogTitle as="h2" className="art:sr-only">
                      Command palette
                    </DialogTitle>
                    <div className="art:flex art:shrink-0 art:items-center art:gap-2 art:border-b art:border-border art:p-3">
                      <div className="art:flex art:h-10 art:min-w-0 art:flex-1 art:items-center art:gap-3 art:rounded-full art:border art:border-border art:px-3 art:focus-within:border-ring">
                        <Svg name="lucide-search" size="art:size-4 art:shrink-0 art:text-muted-foreground">
                          <path d="m21 21-4.34-4.34"/>
                          <circle cx="11" cy="11" r="8"/>
                        </Svg>
                        <input placeholder="Search commands…" aria-label="Search commands…" role="combobox" aria-expanded="true" aria-autocomplete="list" aria-controls={`${id}-results`} aria-activedescendant={count ? `${id}-option-${active}` : undefined} autoComplete="off" spellCheck={false} autoFocus className="art:h-10 art:min-w-0 art:flex-1 art:rounded-full art:bg-transparent art:text-sm art:outline-none art:placeholder:text-muted-foreground" value={query} onChange={(e) => {
                    setQuery(e.target.value);
                    setActive(0);
                }} onKeyDown={onInputKey}/>
                        {query && (<ArtemisMorphicTooltip content="Clear search" side="bottom">
                            <button type="button" className={`${GHOST} art:size-8 art:rounded-full art:focus-visible:ring-2 art:focus-visible:ring-ring`} aria-label="Clear search" tabIndex={0} onClick={() => { setQuery(""); setActive(0); }}>
                              <Svg name="lucide-x" size="art:size-3.5">
                                <path d="M18 6 6 18"/>
                                <path d="m6 6 12 12"/>
                              </Svg>
                            </button>
                          </ArtemisMorphicTooltip>)}
                      </div>
                      <ArtemisMorphicTooltip content="Close palette" side="bottom">
                        <button type="button" className={`${GHOST} art:gap-2 art:h-9 art:shrink-0 art:rounded-full art:px-2 art:text-xs art:focus-visible:ring-2 art:focus-visible:ring-ring`} aria-label="Close palette" tabIndex={0} onClick={close}>
                          <kbd>Esc</kbd>
                        </button>
                      </ArtemisMorphicTooltip>
                    </div>
                    <div ref={listRef} id={`${id}-results`} role="listbox" aria-label="Commands" className="art:min-h-0 art:max-h-[min(50dvh,24rem)] art:overflow-y-auto art:overscroll-contain art:p-2">
                      {count ? (groups.map((g) => (<fieldset key={g.name} aria-label={g.name} className="art:mb-2 art:min-w-0 art:last:mb-0">
                            <p aria-hidden="true" className="art:px-3 art:pb-1.5 art:pt-2 art:text-xs art:text-muted-foreground">
                              {g.name}
                            </p>
                            {g.items.map((c) => {
                        const index = flat.indexOf(c);
                        const on = index === active;
                        return (<button key={c.label} type="button" role="option" aria-selected={on} id={`${id}-option-${index}`} data-index={index} tabIndex={-1} className="art:relative art:isolate art:flex art:min-h-10 art:w-full art:items-center art:gap-3 art:rounded-full art:px-3 art:py-2 art:text-left art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring" onPointerMove={() => !on && setActive(index)} onClick={() => choose(c)}>
                                  {on && <motion.span layoutId={`${id}-active`} className="art:absolute art:inset-0 art:-z-10 art:rounded-full art:bg-muted" transition={reduce ? { duration: 0 } : { duration: 0.3, ease: "easeOut" }}/>}
                                  {c.icon}
                                  <span className="art:min-w-0 art:flex-1">
                                    <span className="art:block art:truncate art:text-sm">{c.label}</span>
                                  </span>
                                  {on && (<Svg name="lucide-corner-down-left" size="art:size-3.5 art:shrink-0 art:text-muted-foreground">
                                      <path d="M20 4v7a4 4 0 0 1-4 4H4"/>
                                      <path d="m9 10-5 5 5 5"/>
                                    </Svg>)}
                                </button>);
                    })}
                          </fieldset>))) : (<div className="art:flex art:min-h-32 art:items-center art:justify-center art:px-6 art:text-center art:text-sm art:text-muted-foreground">No commands found.</div>)}
                    </div>
                    <div className="art:flex art:shrink-0 art:items-center art:gap-4 art:border-t art:border-border art:px-4 art:py-3 art:text-xs art:text-muted-foreground">
                      <span className="art:inline-flex art:items-center art:gap-1">
                        <Svg name="lucide-arrow-up" size="art:size-3">
                          <path d="m5 12 7-7 7 7"/>
                          <path d="M12 19V5"/>
                        </Svg>
                        <Svg name="lucide-arrow-down" size="art:size-3">
                          <path d="M12 5v14"/>
                          <path d="m19 12-7 7-7-7"/>
                        </Svg>
                        <span className="art:ml-1">Navigate</span>
                      </span>
                      <span className="art:inline-flex art:items-center art:gap-1.5">
                        <Svg name="lucide-corner-down-left" size="art:size-3">
                          <path d="M20 4v7a4 4 0 0 1-4 4H4"/>
                          <path d="m9 10-5 5 5 5"/>
                        </Svg>
                        Select
                      </span>
                      <span className="art:ml-auto art:tabular-nums">{count === 1 ? "1 result" : `${count} results`}</span>
                      <output className="art:sr-only">{count === 1 ? "1 command found." : `${count} commands found.`}</output>
                    </div>
                  </motion.div>
                </DialogPanel>
                </MotionConfig>
              </div>)}
          </AnimatePresence>
        </Dialog>)}
    </ArtemisMorphicTooltipProvider>);
}
